<?php
require_once '_bootstrap.php';require_admin_permission('bookings.manage');$db=admin_db();ensure_app_schema($db);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'';if(!in_array($status,['published','hidden'],true))redirect_with_message('reviews.php','Invalid review status.');$db->execute_query('UPDATE booking_reviews SET status=? WHERE id=?',[$status,$id]);admin_audit($db,'review_'.$status,'booking_review',(string)$id);redirect_with_message('reviews.php','Review updated.');}
$pagination=admin_paginate($db,'SELECT COUNT(*) total FROM booking_reviews');
$reviews=$db->query("SELECT r.*,b.booking_reference,b.customer_name,p.name package_name,h.name hotel_name FROM booking_reviews r JOIN bookings b ON b.id=r.booking_id LEFT JOIN packages p ON p.id=r.package_id LEFT JOIN hotels h ON h.id=r.hotel_id ORDER BY r.created_at DESC LIMIT {$pagination['limit']} OFFSET {$pagination['offset']}");
$pageTitle='Reviews';include '_header.php';?>
<div class="page-head"><div><span>Customer feedback</span><h1>Reviews</h1></div><a class="reset-btn" href="bookings.php"><i class="fa-solid fa-arrow-left"></i> Back to bookings</a></div>
<section class="panel"><div class="table-wrap"><table><thead><tr><th>Booking / Customer</th><th>Package</th><th>Hotel</th><th>Ratings</th><th>Review</th><th>Status</th><th>Action</th></tr></thead><tbody><?php while($r=$reviews->fetch_assoc()):?><tr><td><strong><?php echo e($r['booking_reference']?:'#'.$r['booking_id']);?></strong><small><?php echo e($r['customer_name']);?><br><?php echo e($r['user_email']);?></small></td><td><?php echo e($r['package_name']);?></td><td><?php echo e($r['hotel_name']?:'Not assigned');?></td><td><strong>Package <?php echo (int)$r['package_rating'];?>/5</strong><small>Hotel <?php echo (int)$r['hotel_rating'];?>/5</small></td><td><?php echo $r['review_text']?e($r['review_text']):'<span class="muted">No text</span>';?></td><td><span class="pill"><?php echo e($r['status']);?></span></td><td><form method="post"><?php echo csrf_input();?><input type="hidden" name="id" value="<?php echo (int)$r['id'];?>"><input type="hidden" name="status" value="<?php echo $r['status']==='published'?'hidden':'published';?>"><button class="icon-btn" title="Toggle visibility"><i class="fa-solid <?php echo $r['status']==='published'?'fa-eye-slash':'fa-eye';?>"></i></button></form></td></tr><?php endwhile;?></tbody></table></div><?php admin_pagination($pagination);?></section><?php include '_footer.php';?>
